/**
 * <div id="class.mongodb-bson-regex" class="reference"> <h1 class="title">The MongoDB\BSON\Regex class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.0.0)</p>  <div class="section" id="mongodb-bson-regex.intro">   <h2 class="title">简介</h2>   <p class="simpara">    BSON type for a regular expression pattern and optional    <a href="https://www.mongodb.com/docs/manual/reference/operator/query/regex/#op._S_options" class="link external">»&nbsp;flags</a>.   </p>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     <span class="simpara">     This BSON type is mainly used when querying the database. Alternatively,     the     <a href="https://www.mongodb.com/docs/manual/reference/operator/query/regex" class="link external">»&nbsp;\$regex</a>     query operator may be used.    </span>   </p></blockquote>  </div>  <div class="section" id="mongodb-bson-regex.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\BSON\Regex</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-bson-regexinterface.php" class="interfacename">MongoDB\BSON\RegexInterface</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.mongodb-bson-type.php" class="interfacename">MongoDB\BSON\Type</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.jsonserializable.php" class="interfacename">JsonSerializable</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-regex.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$pattern</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$flags</span><span class="initializer"> = ""</span></span>)</div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-regex.getflags.php" class="methodname" style="color:#CC7832">getFlags</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-regex.getpattern.php" class="methodname" style="color:#CC7832">getPattern</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-regex.jsonserialize.php" class="methodname" style="color:#CC7832">jsonSerialize</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-regex.tostring.php" class="methodname" style="color:#CC7832">__toString</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">             <tr>        <td>PECL mongodb 2.0.0</td>        <td>         <span class="simpara">          此类不再实现 <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> 接口。         </span>        </td>       </tr>      <tr>       <td>PECL mongodb 1.12.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a></span> for PHP 8.0+.       </td>      </tr>      <tr>       <td>PECL mongodb 1.3.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-regexinterface.php" class="interfacename">MongoDB\BSON\RegexInterface</a></span>.       </td>      </tr>      <tr>       <td>PECL mongodb 1.2.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> and        <span class="interfacename"><a href="https://php.net/manual/zh/class.jsonserializable.php" class="interfacename">JsonSerializable</a></span>.       </td>      </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\BSON\Regex::__construct} — Construct a new Regex</li><li>{@link MongoDB\BSON\Regex::getFlags} — Returns the Regex's flags</li><li>{@link MongoDB\BSON\Regex::getPattern} — Returns the Regex's pattern</li><li>{@link MongoDB\BSON\Regex::jsonSerialize} — Returns a representation that can be converted to JSON</li><li>{@link MongoDB\BSON\Regex::__toString} — Returns the string representation of this Regex</li></ul></div>
 * 
 * Class Regex
 * @link https://php.net/manual/zh/class.mongodb-bson-regex.php
 */
final class Regex implements RegexInterface, JsonSerializable, Type, Stringable
{
    /**
 * <div id="mongodb-bson-regex.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Regex::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Regex::__construct</span> — <span class="dc-title">Construct a new Regex</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-regex.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Regex::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$pattern</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$flags</span><span class="initializer"> = ""</span></span>)</div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-regex.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">pattern</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      The regular expression pattern.     </span>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:       <span class="simpara">       The pattern should not be wrapped with delimiter characters.      </span>     </p></blockquote>    </dd>          <dt><span class="parameter" style="color:#3A95FF">flags</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      The <a href="https://www.mongodb.com/docs/manual/reference/operator/query/regex/#op._S_options" class="link external">»&nbsp;regular      expression flags</a>. Characters in this argument will be sorted      alphabetically.     </span>    </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-regex.construct-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if <span class="parameter" style="color:#3A95FF">pattern</span> or <span class="parameter" style="color:#3A95FF">flags</span> contain null bytes.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-bson-regex.construct-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.2.0</td>      <td>       <span class="simpara">        The <span class="parameter" style="color:#3A95FF">flags</span> argument is optional and defaults to        an empty string.       </span>       <span class="simpara">        Characters in the <span class="parameter" style="color:#3A95FF">flags</span> argument will be sorted        alphabetically when a Regex is constructed. Previously, the characters        were stored in the order provided.       </span>       <span class="simpara">        <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span>        is thrown if <span class="parameter" style="color:#3A95FF">pattern</span> or        <span class="parameter" style="color:#3A95FF">flags</span> contain null bytes. Previously, values        would be truncated at the first null byte.       </span>      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-regex.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\Regex::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$regex </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\BSON\Regex</span><span style="color: #007700">(</span><span style="color: #DD0000">'^foo'</span><span style="color: #007700">, </span><span style="color: #DD0000">'i'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$regex</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(MongoDB\BSON\Regex)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["pattern"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"^foo"<br>&nbsp;&nbsp;["flags"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"i"<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-regex.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/operator/query/regex/#op._S_options" class="link external">»&nbsp;Supported regular expression flags</a></li>  </ul> </div></div>
 * 
     * Construct a new Regex
     * @link https://php.net/manual/zh/mongodb-bson-regex.construct.php
     */
    final public function __construct(string $pattern, string $flags = '') {}

